window.STORY_V22={"noe":[{"stage":"01 · EL CONTEXTO","name":"Noé","role":"El constructor del arca; el Génesis lo presenta como un hombre justo en un mundo violento.","mode":"historico","title":"Un mundo lleno de violencia","text":"La violencia y la corrupción se habían extendido, pero Noé procuraba andar con Dios en medio de aquel ambiente.","why":"El relato comienza mostrando por qué Jehová decidió intervenir y por qué Noé fue diferente.","reference":"Génesis 6:9–22; 7:1–16"},{"stage":"02 · EL PRIMER CAMBIO","name":"Sem","role":"Uno de los tres hijos de Noé que entraron en el arca.","mode":"historico","title":"La orden de construir un arca","text":"Jehová explicó a Noé que llegaría un diluvio y le dio medidas e instrucciones para una embarcación enorme.","why":"Noé tuvo que actuar mucho antes de ver la lluvia; su obediencia fue práctica.","reference":"Génesis 6:9–22; 7:1–16"},{"stage":"03 · EL DESAFÍO","name":"Esposa de Noé","role":"Esposa de Noé; nombre no registrado.","mode":"historico","title":"Un trabajo de familia","text":"Noé preparó el arca con su familia y reunió los alimentos y lo necesario para sobrevivir.","why":"La tarea exigía perseverancia y cooperación durante un período prolongado.","reference":"Génesis 6:9–22; 7:1–16"},{"stage":"04 · LA RESPUESTA","name":"Jafet","role":"Hijo de Noé que estuvo junto a su familia durante el Diluvio.","mode":"historico","title":"La entrada en el arca","text":"Noé entró en el arca con su esposa, sus tres hijos y sus nueras. También entraron animales según las instrucciones recibidas.","why":"La familia no esperó a que comenzara el desastre para ponerse a salvo.","reference":"Génesis 6:9–22; 7:1–16"},{"stage":"05 · EL PUNTO DECISIVO","name":"Cam","role":"Hijo de Noé y sobreviviente del Diluvio.","mode":"historico","title":"El Diluvio","text":"Comenzó a llover y las aguas aumentaron; quienes estaban dentro del arca quedaron protegidos mientras la Tierra era inundada.","why":"La diferencia entre escuchar una advertencia y actuar fue decisiva.","reference":"Génesis 6:9–22; 7:1–16"},{"stage":"06 · LAS CONSECUENCIAS","name":"Noé","role":"El constructor del arca; el Génesis lo presenta como un hombre justo en un mundo violento.","mode":"historico","title":"Un nuevo comienzo","text":"Después de que bajaron las aguas, Noé y su familia salieron del arca. Jehová estableció un pacto relacionado con el arcoíris.","why":"La historia termina con un nuevo comienzo y la promesa de que no habría otro diluvio mundial.","reference":"Génesis 6:9–22; 7:1–16"}],"abrahan":[{"stage":"01 · EL CONTEXTO","name":"Abrahán","role":"Patriarca que salió de Ur por fe y recibió promesas de Jehová.","mode":"historico","title":"La vida en Ur","text":"Abrahán y Sara vivían en Ur, una ciudad importante de Mesopotamia. Dejar ese entorno suponía despedirse de una forma de vida establecida.","why":"Su fe no comenzó con una respuesta a todas sus preguntas, sino con disposición a escuchar.","reference":"Génesis 12:1–9"},{"stage":"02 · EL PRIMER CAMBIO","name":"Taré","role":"Padre de Abrahán, que salió con la familia de Ur hacia Harán.","mode":"historico","title":"Viaje hasta Harán","text":"La familia salió de Ur y se estableció por un tiempo en Harán; Taré, el padre de Abrahán, formó parte de esa etapa del recorrido.","why":"El viaje tuvo etapas, no fue un único traslado instantáneo.","reference":"Génesis 12:1–9"},{"stage":"03 · EL DESAFÍO","name":"Sara","role":"Esposa de Abrahán, que compartió sus viajes y desafíos.","mode":"historico","title":"Una promesa para el futuro","text":"Jehová le dijo a Abrahán que saliera hacia la tierra que le mostraría y le prometió bendiciones relacionadas con su descendencia.","why":"Abrahán recibió dirección y promesas, aunque todavía no conocía todos los detalles.","reference":"Génesis 12:1–9"},{"stage":"04 · LA RESPUESTA","name":"Lot","role":"Sobrino de Abrahán, quien viajó con él hacia Canaán.","mode":"historico","title":"Entrada en Canaán","text":"Abrahán salió de Harán acompañado por Sara y Lot, y llegó a la tierra de Canaán. Allí siguió viviendo como residente extranjero.","why":"La confianza se manifestó en decisiones concretas, como abandonar un lugar conocido.","reference":"Génesis 12:1–9"},{"stage":"05 · EL PUNTO DECISIVO","name":"Sara","role":"Esposa de Abrahán; recorrió Canaán con él.","mode":"historico","title":"Altares y adoración","text":"En Canaán, Abrahán construyó altares e invocó el nombre de Jehová en lugares como Siquem y Betel.","why":"La adoración siguió siendo central durante sus desplazamientos.","reference":"Génesis 12:1–9"},{"stage":"06 · LAS CONSECUENCIAS","name":"Sara","role":"Esposa de Abrahán, que compartió sus viajes y desafíos.","mode":"historico","title":"Una vida de fe perseverante","text":"Abrahán y Sara continuaron viviendo en tiendas mientras aguardaban el cumplimiento de las promesas divinas.","why":"La fe de Abrahán se ve en un camino largo, no solo en un primer paso valiente.","reference":"Génesis 12:1–9"}],"jose":[{"stage":"01 · EL CONTEXTO","name":"José","role":"Hijo de Jacob; vendido como esclavo por sus hermanos.","mode":"historico","title":"Una juventud marcada por los celos","text":"José recibió de su padre una túnica especial y contó sueños que provocaron la envidia de sus hermanos. Fue vendido y llevado a Egipto.","why":"Así se entiende por qué un joven israelita terminó trabajando lejos de su familia.","reference":"Génesis 37:3-36"},{"stage":"02 · EL PRIMER CAMBIO","name":"José","role":"Siervo fiel en la casa de Potifar.","mode":"historico","title":"La tentación y la acusación","text":"En Egipto, José ganó la confianza de Potifar. Rechazó las propuestas de su esposa y terminó encarcelado tras una acusación falsa.","why":"Hizo lo correcto aunque eso le causó sufrimiento.","reference":"Génesis 39:1-23"},{"stage":"03 · EL DESAFÍO","name":"José","role":"Prisionero que interpretó los sueños de sus compañeros.","mode":"historico","title":"Los sueños en la prisión","text":"José interpretó los sueños del copero y del panadero del faraón. Los acontecimientos sucedieron como había dicho, pero el copero lo olvidó durante un tiempo.","why":"Este período muestra paciencia y capacidad de ayudar incluso en la cárcel.","reference":"Génesis 40:1-23"},{"stage":"04 · LA RESPUESTA","name":"José","role":"Intérprete de los sueños reales y administrador de Egipto.","mode":"historico","title":"Del calabozo al palacio","text":"El faraón soñó con siete años de abundancia y siete de hambre. José explicó los sueños y recomendó almacenar reservas. El faraón le encargó la tarea.","why":"La previsión de José permitió que hubiera alimento durante la escasez.","reference":"Génesis 41:1-57"},{"stage":"05 · EL PUNTO DECISIVO","name":"Judá","role":"Uno de los hermanos de José.","mode":"historico","title":"Regreso a Egipto durante el hambre","text":"Los hermanos de José llegaron a Egipto en busca de alimento. José los reconoció, puso a prueba sus intenciones y exigió ver a Benjamín.","why":"El encuentro revelaría si habían cambiado después de tratar cruelmente a José.","reference":"Génesis 42:1-38; 43:1-34"},{"stage":"06 · LAS CONSECUENCIAS","name":"José","role":"Hermano que decidió perdonar y reunirse con su familia.","mode":"historico","title":"Perdón y reencuentro","text":"Judá se ofreció a quedarse por Benjamín; José reveló quién era, lloró con sus hermanos y la familia terminó reuniéndose en Egipto.","why":"El desenlace muestra la posibilidad de reparar vínculos después de una injusticia grave.","reference":"Génesis 44:18-34; 45:1-15; 46:28-30"}],"moises":[{"stage":"01 · EL CONTEXTO","name":"Moisés","role":"Líder de Israel durante la salida de Egipto.","mode":"historico","title":"Una infancia bajo amenaza","text":"En Egipto, la madre y la hermana de Moisés lo protegieron cuando el faraón ordenó matar a los niños israelitas.","why":"Su supervivencia estuvo ligada al valor y a la iniciativa de su familia.","reference":"Éxodo 1:22; 2:1-10"},{"stage":"02 · EL PRIMER CAMBIO","name":"Moisés","role":"Hermano de Moisés que lo ayudó a hablar ante el pueblo y el faraón.","mode":"historico","title":"Criado en Egipto y una decisión de fe","text":"Moisés creció con acceso a la corte egipcia, pero más tarde escogió identificarse con el pueblo de Israel.","why":"La decisión muestra que su fe pesó más que los privilegios de la corte.","reference":"Éxodo 2:10-15; Hebreos 11:24-26"},{"stage":"03 · EL DESAFÍO","name":"Aarón","role":"Hermana de Moisés y profetisa del pueblo israelita.","mode":"historico","title":"El encargo de liberar a Israel","text":"Moisés volvió a Egipto con Aarón y hablaron al faraón. Como este se resistió, tuvieron lugar las plagas.","why":"La liberación no dependió de la autoridad de Moisés, sino de Jehová.","reference":"Éxodo 4:27-31; 7-12"},{"stage":"04 · LA RESPUESTA","name":"Moisés","role":"Líder de Israel a orillas del mar Rojo.","mode":"historico","title":"Del éxodo a las orillas del mar Rojo","text":"Los israelitas salieron de Egipto, pero pronto vieron acercarse al ejército del faraón y sintieron miedo.","why":"Ese momento puso a prueba su confianza y mostró la importancia del liderazgo.","reference":"Éxodo 12:31-42; 14:5-14"},{"stage":"05 · EL PUNTO DECISIVO","name":"Moisés","role":"Líder de Israel durante la salida de Egipto.","mode":"historico","title":"El camino a través del mar","text":"Jehová hizo que el mar se separara y los israelitas cruzaron por terreno seco.","why":"La liberación quedó presentada como un acontecimiento decisivo en la historia de Israel.","reference":"Éxodo 14:15-29"},{"stage":"06 · LAS CONSECUENCIAS","name":"Míriam","role":"Hermana de Moisés y profetisa del pueblo israelita.","mode":"historico","title":"Un cántico después de cruzar","text":"Israel llegó a salvo al otro lado, y Míriam dirigió a las mujeres en un cántico de agradecimiento.","why":"El desenlace de la historia une liberación y gratitud.","reference":"Éxodo 15:1-21"}],"rahab":[{"stage":"01 · EL CONTEXTO","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"Una mujer en Jericó","text":"Rahab vivía en Jericó, una ciudad que iba a verse afectada por la entrada de Israel en Canaán.","why":"Su decisión se tomó cuando el futuro de su ciudad era incierto.","reference":"Josué 2:1–21; 6:22–25"},{"stage":"02 · EL PRIMER CAMBIO","name":"Dos espías israelitas","role":"Enviados por Josué; sus nombres no se mencionan.","mode":"historico","title":"Llegan dos espías","text":"Dos mensajeros israelitas llegaron a la ciudad para examinar la situación. Rahab les dio alojamiento y los escondió.","why":"Ayudarlos implicaba un riesgo personal.","reference":"Josué 2:1–21; 6:22–25"},{"stage":"03 · EL DESAFÍO","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"Por qué decidió ayudarlos","text":"Rahab había oído lo que Jehová había hecho por Israel y expresó que reconocía su poder.","why":"Su manera de actuar estuvo relacionada con lo que había aprendido.","reference":"Josué 2:1–21; 6:22–25"},{"stage":"04 · LA RESPUESTA","name":"Familia de Rahab","role":"Padres y familiares por quienes Rahab pidió protección.","mode":"historico","title":"Una petición por su familia","text":"Rahab pidió protección para su padre, su madre y los demás miembros de su familia. Los mensajeros le dieron instrucciones para identificarlos.","why":"Pensó también en la seguridad de sus seres queridos.","reference":"Josué 2:1–21; 6:22–25"},{"stage":"05 · EL PUNTO DECISIVO","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"La cuerda escarlata","text":"Rahab debía colocar una cuerda roja en su ventana y reunir a su familia en su casa.","why":"La señal tenía que ir acompañada de seguir las instrucciones.","reference":"Josué 2:1–21; 6:22–25"},{"stage":"06 · LAS CONSECUENCIAS","name":"Rahab","role":"Mujer de Jericó que dio refugio a mensajeros israelitas.","mode":"historico","title":"Una familia rescatada","text":"Cuando Jericó fue conquistada, Rahab y quienes estaban con ella en la casa fueron librados.","why":"El desenlace conecta fe, valor y acciones concretas.","reference":"Josué 2:1–21; 6:22–25"}],"rut":[{"stage":"01 · EL CONTEXTO","name":"Noemí","role":"Israelita viuda que regresó de Moab a Belén.","mode":"historico","title":"Pérdidas en Moab","text":"Noemí había perdido a su esposo y a sus dos hijos. Sus nueras Rut y Orpá también habían enviudado.","why":"La historia comienza en un momento de dolor e incertidumbre.","reference":"Rut 1:16–22; 2:1–17"},{"stage":"02 · EL PRIMER CAMBIO","name":"Noemí","role":"Israelita viuda que regresó de Moab a Belén.","mode":"historico","title":"La decisión de volver","text":"Noemí se enteró de que había alimento en Judá y decidió regresar desde Moab a Belén.","why":"Volver significaba empezar de nuevo con muy pocos recursos.","reference":"Rut 1:16–22; 2:1–17"},{"stage":"03 · EL DESAFÍO","name":"Rut","role":"Moabita que eligió acompañar lealmente a Noemí.","mode":"historico","title":"Rut decide acompañarla","text":"Aunque Noemí le ofreció volver con los suyos, Rut eligió quedarse a su lado y adorar a su Dios.","why":"La lealtad de Rut no fue solo una emoción: cambió su futuro.","reference":"Rut 1:16–22; 2:1–17"},{"stage":"04 · LA RESPUESTA","name":"Noemí","role":"Suegra de Rut; regresó con ella a Belén.","mode":"historico","title":"Llegada a Belén","text":"Rut y Noemí llegaron a Belén al comienzo de la cosecha de cebada.","why":"Ese momento abrió una oportunidad práctica de conseguir alimento.","reference":"Rut 1:16–22; 2:1–17"},{"stage":"05 · EL PUNTO DECISIVO","name":"Boaz","role":"Propietario israelita que mostró bondad a Rut y Noemí.","mode":"historico","title":"En el campo de Boaz","text":"Rut recogió espigas detrás de los segadores en un campo de Boaz, quien se interesó por su bienestar.","why":"La bondad y la generosidad aparecen junto con el trabajo diligente.","reference":"Rut 1:16–22; 2:1–17"},{"stage":"06 · LAS CONSECUENCIAS","name":"Rut","role":"Moabita que eligió acompañar lealmente a Noemí.","mode":"historico","title":"Una familia y una esperanza","text":"Boaz se casó con Rut; con el tiempo, su familia quedó vinculada al linaje del rey David.","why":"Una historia de pérdidas terminó dando lugar a una nueva etapa familiar.","reference":"Rut 1:16–22; 2:1–17"}],"samuel":[{"stage":"01 · EL CONTEXTO","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"Un niño en el tabernáculo","text":"Samuel servía a Jehová en el tabernáculo bajo la supervisión del sacerdote Elí.","why":"Era joven, pero ya participaba en labores de servicio.","reference":"1 Samuel 3:1–10"},{"stage":"02 · EL PRIMER CAMBIO","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"Una voz durante la noche","text":"Una noche Samuel oyó que alguien lo llamaba y fue a ver a Elí porque pensó que el sacerdote necesitaba algo.","why":"Samuel reaccionó con disposición a ayudar, aunque aún no comprendía quién lo llamaba.","reference":"1 Samuel 3:1–10"},{"stage":"03 · EL DESAFÍO","name":"Elí","role":"Sacerdote que supervisaba a Samuel en el tabernáculo.","mode":"historico","title":"La confusión se repite","text":"Samuel escuchó de nuevo su nombre y volvió a acudir a Elí. Esto ocurrió varias veces.","why":"La repetición mostró que necesitaba orientación para entender lo sucedido.","reference":"1 Samuel 3:1–10"},{"stage":"04 · LA RESPUESTA","name":"Elí","role":"Sacerdote que supervisaba a Samuel en el tabernáculo.","mode":"historico","title":"El consejo de Elí","text":"Elí comprendió que Jehová estaba llamando al muchacho y le explicó cómo responder.","why":"La guía de alguien con experiencia ayudó a Samuel.","reference":"1 Samuel 3:1–10"},{"stage":"05 · EL PUNTO DECISIVO","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"El mensaje que recibió","text":"Cuando volvió a escuchar la voz, Samuel se dispuso a escuchar. Recibió un mensaje serio para la casa de Elí.","why":"Escuchar también implicaría transmitir algo difícil.","reference":"1 Samuel 3:1–10"},{"stage":"06 · LAS CONSECUENCIAS","name":"Samuel","role":"Joven que servía en el tabernáculo y llegó a ser profeta.","mode":"historico","title":"Samuel crece como profeta","text":"Samuel fue reconocido como profeta fiel, y Jehová continuó utilizándolo para orientar a Israel.","why":"Su disposición a escuchar de joven marcó el comienzo de una vida de servicio.","reference":"1 Samuel 3:1–10"}],"jonatan":[{"stage":"01 · EL CONTEXTO","name":"Jonatán","role":"Hijo del rey Saúl y amigo leal de David.","mode":"historico","title":"Dos hombres y una amistad","text":"Jonatán era hijo de Saúl y heredero del trono; David se había distinguido por su valor. Entre ambos surgió una amistad muy estrecha.","why":"Jonatán no dejó que su posición social impidiera valorar a David.","reference":"1 Samuel 18:1–4; 23:16–18"},{"stage":"02 · EL PRIMER CAMBIO","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"Un pacto de amistad","text":"Jonatán y David hicieron un pacto y Jonatán mostró afecto generoso hacia él.","why":"La amistad se basaba en lealtad, no en conveniencia.","reference":"1 Samuel 18:1–4; 23:16–18"},{"stage":"03 · EL DESAFÍO","name":"Saúl","role":"Primer rey de Israel, padre de Jonatán.","mode":"historico","title":"La oposición de Saúl","text":"Saúl llegó a considerar a David una amenaza y trató de hacerle daño.","why":"Jonatán tuvo que elegir entre la hostilidad de su padre y lo que era justo.","reference":"1 Samuel 18:1–4; 23:16–18"},{"stage":"04 · LA RESPUESTA","name":"Jonatán","role":"Hijo del rey Saúl y amigo leal de David.","mode":"historico","title":"Advertencia a David","text":"Jonatán ayudó a David a conocer el peligro y a evitar que lo alcanzaran.","why":"Su lealtad implicó actuar cuando un amigo estaba en peligro.","reference":"1 Samuel 18:1–4; 23:16–18"},{"stage":"05 · EL PUNTO DECISIVO","name":"Jonatán","role":"Hijo del rey Saúl y amigo leal de David.","mode":"historico","title":"Un encuentro en el desierto","text":"Cuando David estaba escondido, Jonatán fue a verlo y lo fortaleció para que siguiera confiando en Dios.","why":"No basta con sentir aprecio: una palabra oportuna puede sostener a otro.","reference":"1 Samuel 18:1–4; 23:16–18"},{"stage":"06 · LAS CONSECUENCIAS","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"Lealtad hasta el final","text":"La amistad de ambos quedó como un ejemplo de apoyo sincero, incluso cuando sus circunstancias eran muy diferentes.","why":"La lealtad se demuestra en momentos difíciles.","reference":"1 Samuel 18:1–4; 23:16–18"}],"abigail":[{"stage":"01 · EL CONTEXTO","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"Una petición rechazada","text":"David envió mensajeros para pedir ayuda a Nabal, un hombre rico a cuyos pastores los hombres de David habían protegido.","why":"El intercambio pudo resolverse de manera pacífica, pero no fue así.","reference":"1 Samuel 25:14–35"},{"stage":"02 · EL PRIMER CAMBIO","name":"Nabal","role":"Esposo de Abigaíl, cuya respuesta imprudente provocó un conflicto.","mode":"historico","title":"Una respuesta ofensiva","text":"Nabal respondió de forma despectiva, y David se enfureció al enterarse.","why":"Una provocación estaba a punto de provocar daños mucho mayores.","reference":"1 Samuel 25:14–35"},{"stage":"03 · EL DESAFÍO","name":"Joven servidor de Nabal","role":"Siervo que avisó a Abigaíl del peligro.","mode":"historico","title":"Un sirviente avisa","text":"Un servidor informó a Abigaíl, esposa de Nabal, sobre el peligro que se acercaba.","why":"Alguien tuvo la sensatez de buscar ayuda antes de que fuera tarde.","reference":"1 Samuel 25:14–35"},{"stage":"04 · LA RESPUESTA","name":"Abigaíl","role":"Mujer sensata que intervino para impedir una venganza.","mode":"historico","title":"Abigaíl prepara provisiones","text":"Sin perder tiempo, Abigaíl reunió alimentos y salió al encuentro de David.","why":"Su iniciativa fue rápida, concreta y orientada a evitar violencia.","reference":"1 Samuel 25:14–35"},{"stage":"05 · EL PUNTO DECISIVO","name":"Abigaíl","role":"Mujer sensata que intervino para impedir una venganza.","mode":"historico","title":"Palabras de paz","text":"Abigaíl habló con humildad y razonó con David para impedir una venganza impulsiva.","why":"Su tacto ayudó a cambiar el curso de los acontecimientos.","reference":"1 Samuel 25:14–35"},{"stage":"06 · LAS CONSECUENCIAS","name":"David","role":"Futuro rey de Israel; su amistad con Jonatán es muy conocida.","mode":"historico","title":"David escucha","text":"David aceptó el consejo y renunció a su propósito de vengarse de Nabal.","why":"Escuchar una corrección oportuna puede evitar errores irreparables.","reference":"1 Samuel 25:14–35"}],"salomon":[{"stage":"01 · EL CONTEXTO","name":"Salomón","role":"Hijo de David y rey de Israel, conocido por su sabiduría y el templo de Jerusalén.","mode":"historico","title":"Un rey preparado para una gran tarea","text":"David animó a su hijo Salomón a obedecer a Jehová y le dejó preparativos para el templo. Salomón heredó el trono.","why":"El propósito de construir el templo comenzó antes del proyecto de obra.","reference":"1 Crónicas 28:9-21; 1 Reyes 2:1-4","verseLabel":"1 Reyes 2:12","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/2/"},{"stage":"02 · EL PRIMER CAMBIO","name":"Salomón","role":"Hijo de David y rey de Israel, conocido por su sabiduría y el templo de Jerusalén.","mode":"historico","title":"Una petición en Gabaón","text":"En Gabaón, Jehová se apareció a Salomón en un sueño y lo invitó a pedir algo. Salomón no pidió riquezas ni una larga vida: pidió un corazón obediente para juzgar bien al pueblo.","why":"Jehová aprobó esa petición y le concedió sabiduría, además de otras bendiciones.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 3:4-15","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/3/"},{"stage":"03 · EL DESAFÍO","name":"Madre de la criatura","role":"Mujer cuyo nombre no aparece en el episodio del juicio.","mode":"historico","title":"El juicio de las dos madres","text":"Dos mujeres afirmaban ser la madre de un mismo bebé. Salomón propuso una prueba que reveló cuál de ellas amaba tanto al niño que prefería renunciar a él antes que verlo morir.","why":"Israel quedó impresionado porque reconoció la sabiduría de Dios en la decisión.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 3:16-28","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/3/"},{"stage":"04 · LA RESPUESTA","name":"Hiram de Tiro","role":"Rey de Tiro que colaboró con Salomón en el suministro de madera y materiales.","mode":"historico","title":"El templo empieza a levantarse","text":"Siguiendo los preparativos de David, Salomón organizó obreros, materiales y madera de cedro obtenida mediante acuerdos con Hiram, rey de Tiro. El templo se construyó en Jerusalén.","why":"El trabajo duró aproximadamente siete años y reunió a muchos trabajadores capacitados.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 5-6","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/6/"},{"stage":"05 · EL PUNTO DECISIVO","name":"Sacerdotes del templo","role":"Grupo que participó en la dedicación del templo.","mode":"historico","title":"La dedicación del templo","text":"Cuando terminaron las obras, llevaron el arca del pacto al templo. Salomón hizo una oración pública reconociendo que ningún edificio puede contener a Jehová, y pidió que escuchara las oraciones de su pueblo.","why":"Según 2 Crónicas 7, fuego del cielo consumió las ofrendas y el pueblo se alegró.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 8; 2 Crónicas 7:1","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/8/"},{"stage":"06 · LAS CONSECUENCIAS","name":"Reina de Saba","role":"Soberana que viajó para comprobar la sabiduría de Salomón.","mode":"historico","title":"La reina de Saba y lo que siguió","text":"La reina de Saba llegó con preguntas difíciles para poner a prueba la fama de Salomón. Sus respuestas y la prosperidad del reino la impresionaron. Sin embargo, más adelante Salomón permitió influencias que lo apartaron de la adoración fiel.","why":"La historia enseña que adquirir sabiduría es importante, pero seguir obedeciendo durante toda la vida también lo es.","reference":"1 Reyes 3:5–12","verseLabel":"1 Reyes 10-11","verseUrl":"https://www.jw.org/es/biblioteca/biblia/biblia-estudio/libros/1-reyes/10/"}],"viuda":[{"stage":"01 · EL CONTEXTO","name":"Viuda de Sarepta","role":"Mujer cuyo nombre no se conserva en el relato; ayudó a Elías durante una gran escasez.","mode":"historico","title":"Una época de sequía","text":"Durante una gran sequía, la comida escaseaba y una viuda en Sarepta tenía muy pocas provisiones para ella y su hijo.","why":"La situación planteaba una necesidad inmediata de supervivencia.","reference":"1 Reyes 17:8–16"},{"stage":"02 · EL PRIMER CAMBIO","name":"Elías","role":"Profeta que recibió ayuda y alimento durante una época de sequía.","mode":"historico","title":"Elías llega a Sarepta","text":"El profeta Elías, siguiendo las instrucciones de Jehová, encontró a la viuda recogiendo leña.","why":"El encuentro parecía común, pero dio comienzo a una prueba de confianza.","reference":"1 Reyes 17:8–16"},{"stage":"03 · EL DESAFÍO","name":"Viuda de Sarepta","role":"Mujer cuyo nombre no se conserva en el relato; ayudó a Elías durante una gran escasez.","mode":"historico","title":"Una petición difícil","text":"Elías pidió agua y un poco de pan. La mujer explicó que apenas tenía harina y aceite para una última comida.","why":"La petición tenía un gran peso dadas sus circunstancias.","reference":"1 Reyes 17:8–16"},{"stage":"04 · LA RESPUESTA","name":"Elías","role":"Profeta que recibió ayuda y alimento durante una época de sequía.","mode":"historico","title":"La decisión de compartir","text":"Elías le aseguró que Jehová proveería. La viuda preparó alimento y lo compartió con él.","why":"La mujer actuó a pesar de la escasez que la rodeaba.","reference":"1 Reyes 17:8–16"},{"stage":"05 · EL PUNTO DECISIVO","name":"Viuda de Sarepta","role":"Mujer cuyo nombre no se conserva en el relato; ayudó a Elías durante una gran escasez.","mode":"historico","title":"Harina y aceite suficientes","text":"Durante ese período, la harina y el aceite no se agotaron, tal como se había anunciado.","why":"El relato muestra provisión diaria, no una desaparición inmediata de toda dificultad.","reference":"1 Reyes 17:8–16"},{"stage":"06 · LAS CONSECUENCIAS","name":"Viuda de Sarepta","role":"Mujer que sobrevivió con su hijo durante la sequía.","mode":"historico","title":"Lo que enseña Sarepta","text":"La viuda y su hijo pudieron seguir alimentándose durante la sequía.","why":"En momentos de preocupación, la confianza puede demostrarse en actos concretos de generosidad.","reference":"1 Reyes 17:8–16"}],"naaman":[{"stage":"01 · EL CONTEXTO","name":"Naamán","role":"Jefe del ejército de Siria que sufría una enfermedad de la piel.","mode":"historico","title":"Un jefe militar enfermo","text":"Naamán era un jefe del ejército sirio muy respetado, pero padecía una grave enfermedad de la piel.","why":"La posición social no eliminaba sus problemas personales.","reference":"2 Reyes 5:1–15"},{"stage":"02 · EL PRIMER CAMBIO","name":"Niña israelita","role":"Joven cautiva cuyo nombre no se conoce; habló de Eliseo a la familia de Naamán.","mode":"historico","title":"Una niña israelita habla","text":"Una joven israelita cautiva que trabajaba para la esposa de Naamán dijo que el profeta Eliseo podía ayudarlo.","why":"Una persona sin poder político compartió una información decisiva.","reference":"2 Reyes 5:1–15"},{"stage":"03 · EL DESAFÍO","name":"Naamán","role":"Jefe del ejército de Siria que sufría una enfermedad de la piel.","mode":"historico","title":"El viaje a Israel","text":"Naamán viajó llevando regalos y una carta. Finalmente llegó a la casa de Eliseo.","why":"Esperaba recibir ayuda y quizá un trato especial.","reference":"2 Reyes 5:1–15"},{"stage":"04 · LA RESPUESTA","name":"Eliseo","role":"Profeta de Jehová que dio a Naamán las instrucciones para curarse.","mode":"historico","title":"Instrucciones inesperadas","text":"Eliseo envió un mensaje: Naamán debía bañarse siete veces en el río Jordán. Naamán se molestó porque esperaba una ceremonia más impresionante.","why":"Su orgullo casi le impide aceptar una solución sencilla.","reference":"2 Reyes 5:1–15"},{"stage":"05 · EL PUNTO DECISIVO","name":"Siervos de Naamán","role":"Acompañantes que lo persuadieron de obedecer.","mode":"historico","title":"Los servidores razonan","text":"Los acompañantes de Naamán lo animaron a seguir las indicaciones aunque parecieran demasiado simples.","why":"Escuchar a quienes nos ayudan puede cambiar una reacción impulsiva.","reference":"2 Reyes 5:1–15"},{"stage":"06 · LAS CONSECUENCIAS","name":"Naamán","role":"Jefe del ejército de Siria que sufría una enfermedad de la piel.","mode":"historico","title":"La curación","text":"Naamán se sumergió siete veces en el Jordán y quedó sano. Después reconoció al Dios de Israel.","why":"La humildad y la obediencia terminaron siendo más importantes que el prestigio.","reference":"2 Reyes 5:1–15"}],"jonas":[{"stage":"01 · EL CONTEXTO","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Una misión a Nínive","text":"Jehová encargó a Jonás que advirtiera a los habitantes de Nínive sobre su conducta.","why":"El profeta recibió una tarea que no deseaba cumplir.","reference":"Jonás 3:1–10; 4:1–11"},{"stage":"02 · EL PRIMER CAMBIO","name":"Marineros","role":"Grupo que estuvo con Jonás durante la tormenta.","mode":"historico","title":"Huida por mar","text":"Jonás tomó un barco con destino contrario al que debía ir. Durante el viaje surgió una fuerte tormenta.","why":"Huir de la responsabilidad no eliminó el problema.","reference":"Jonás 3:1–10; 4:1–11"},{"stage":"03 · EL DESAFÍO","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Una experiencia extraordinaria","text":"Jonás fue arrojado al mar y un gran pez lo tragó. Desde su interior oró, y después fue devuelto a tierra firme.","why":"Aquella experiencia le dio una nueva oportunidad.","reference":"Jonás 3:1–10; 4:1–11"},{"stage":"04 · LA RESPUESTA","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Nínive escucha","text":"Jonás fue finalmente a Nínive y proclamó el aviso. Los habitantes tomaron en serio el mensaje y cambiaron su conducta.","why":"La reacción de la ciudad contrastó con las expectativas de Jonás.","reference":"Jonás 3:1–10; 4:1–11"},{"stage":"05 · EL PUNTO DECISIVO","name":"Jonás","role":"Profeta enviado a anunciar una advertencia en Nínive.","mode":"historico","title":"Jonás se disgusta","text":"Cuando Jehová mostró compasión, Jonás se enojó porque Nínive no fue destruida.","why":"Cumplir una tarea no siempre significa comprender todavía el corazón de quien la encargó.","reference":"Jonás 3:1–10; 4:1–11"},{"stage":"06 · LAS CONSECUENCIAS","name":"Jonás","role":"Profeta a quien se enseñó una lección de misericordia.","mode":"historico","title":"La lección de la planta","text":"Jehová utilizó una planta y su pérdida para ayudar a Jonás a reflexionar sobre la compasión por otras personas.","why":"La misericordia fue la lección final de esta historia.","reference":"Jonás 3:1–10; 4:1–11"}],"josias":[{"stage":"01 · EL CONTEXTO","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"Un niño rey","text":"Josías llegó a ser rey de Judá cuando tenía solo ocho años.","why":"Su edad no impidió que con el tiempo buscara hacer lo correcto.","reference":"2 Reyes 22:8–13; 23:1–3"},{"stage":"02 · EL PRIMER CAMBIO","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"El deseo de agradar a Dios","text":"Mientras crecía, Josías quiso restablecer la adoración a Jehová y dejar atrás prácticas incorrectas.","why":"El cambio comenzó antes del descubrimiento del libro.","reference":"2 Reyes 22:8–13; 23:1–3"},{"stage":"03 · EL DESAFÍO","name":"Hilquías","role":"Sumo sacerdote que halló el libro de la Ley durante reparaciones del templo.","mode":"historico","title":"Reparaciones del templo","text":"Se organizaron trabajos para reparar el templo, que había sufrido descuido.","why":"Restaurar un lugar de adoración implicaba esfuerzo y administración.","reference":"2 Reyes 22:8–13; 23:1–3"},{"stage":"04 · LA RESPUESTA","name":"Safán","role":"Secretario que leyó ante Josías el contenido del libro encontrado.","mode":"historico","title":"Encuentran el libro de la Ley","text":"Durante las obras, el sumo sacerdote Hilquías encontró el libro de la Ley y se lo entregó al secretario Safán.","why":"El hallazgo puso delante del rey las normas que muchos habían desatendido.","reference":"2 Reyes 22:8–13; 23:1–3"},{"stage":"05 · EL PUNTO DECISIVO","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"Josías escucha","text":"Safán leyó el libro ante el rey. Josías reaccionó con gran preocupación al comprender cuánto se había apartado el pueblo de la Ley.","why":"Su reacción mostró respeto por lo que había aprendido.","reference":"2 Reyes 22:8–13; 23:1–3"},{"stage":"06 · LAS CONSECUENCIAS","name":"Josías","role":"Rey de Judá que empezó a gobernar siendo niño e impulsó reformas.","mode":"historico","title":"Medidas de reforma","text":"Josías reunió al pueblo, renovó el pacto y promovió acciones para abandonar la idolatría.","why":"La comprensión del mensaje llevó a cambios visibles.","reference":"2 Reyes 22:8–13; 23:1–3"}],"daniel":[{"stage":"01 · EL CONTEXTO","name":"Daniel","role":"Siervo de Jehová y funcionario en Babilonia y bajo el dominio medopersa.","mode":"historico","title":"Un joven lejos de Jerusalén","text":"Daniel y tres compañeros fueron llevados a Babilonia y recibieron formación para servir en la corte.","why":"Desde su juventud, Daniel mostró la importancia de mantener sus convicciones.","reference":"Daniel 1:1-21"},{"stage":"02 · EL PRIMER CAMBIO","name":"Funcionarios del reino","role":"Funcionarios que estaban celosos de Daniel.","mode":"historico","title":"Una prohibición calculada","text":"Algunos funcionarios impulsaron un decreto que impedía dirigir peticiones a otro que no fuera el rey durante cierto tiempo.","why":"La trampa se diseñó para aprovechar la costumbre de Daniel de orar a Jehová.","reference":"Daniel 6:4–23"},{"stage":"03 · EL DESAFÍO","name":"Daniel","role":"Siervo de Jehová y funcionario en Babilonia y bajo el dominio medopersa.","mode":"historico","title":"Daniel sigue orando","text":"Daniel continuó orando tres veces al día, como hacía antes de la prohibición.","why":"No cambió su adoración solo porque otros intentaran presionarlo.","reference":"Daniel 6:4–23"},{"stage":"04 · LA RESPUESTA","name":"Rey Darío","role":"Rey que tuvo que aplicar la ley que había firmado.","mode":"historico","title":"El hoyo de los leones","text":"Los funcionarios lo denunciaron, y el rey se vio obligado a ordenar que Daniel fuera arrojado al hoyo.","why":"La decisión de mantenerse fiel tuvo una consecuencia peligrosa.","reference":"Daniel 6:4–23"},{"stage":"05 · EL PUNTO DECISIVO","name":"Daniel","role":"Siervo de Jehová y funcionario en Babilonia y bajo el dominio medopersa.","mode":"historico","title":"La noche de protección","text":"Daniel pasó la noche entre leones. Según el relato, Jehová envió un ángel que les cerró la boca.","why":"La intervención divina es el momento decisivo de la historia.","reference":"Daniel 6:4–23"},{"stage":"06 · LAS CONSECUENCIAS","name":"Rey Darío","role":"Gobernante que fue informado de que Daniel había sido arrojado a los leones.","mode":"historico","title":"Una noticia al amanecer","text":"El rey fue al hoyo muy temprano y encontró a Daniel vivo.","why":"El final confirma por qué la fidelidad de Daniel se recuerda tanto.","reference":"Daniel 6:4–23"}],"ester":[{"stage":"01 · EL CONTEXTO","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"Una joven llega a ser reina","text":"Ester, una joven judía criada por su primo Mardoqueo, llegó a ser reina en Persia.","why":"Su nueva posición la colocó cerca de decisiones que afectarían a muchas personas.","reference":"Ester 4:10–17; 5:1–8; 7:1–6"},{"stage":"02 · EL PRIMER CAMBIO","name":"Mardoqueo","role":"Primo de Ester que la había criado y la animó a actuar.","mode":"historico","title":"El plan de Hamán","text":"Hamán ideó un plan para exterminar a los judíos del imperio y consiguió una orden real.","why":"El peligro amenazaba a todo el pueblo de Ester.","reference":"Ester 4:10–17; 5:1–8; 7:1–6"},{"stage":"03 · EL DESAFÍO","name":"Mardoqueo","role":"Primo de Ester que la había criado y la animó a actuar.","mode":"historico","title":"Mardoqueo pide ayuda","text":"Mardoqueo pidió a Ester que interviniera ante el rey. Acercarse al rey sin invitación podía poner en riesgo su vida.","why":"Ester tuvo que valorar tanto el peligro como la responsabilidad.","reference":"Ester 4:10–17; 5:1–8; 7:1–6"},{"stage":"04 · LA RESPUESTA","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"Preparación antes de actuar","text":"Ester solicitó que los judíos ayunaran y se preparó para presentarse ante el rey.","why":"No improvisó: buscó apoyo y eligió con cuidado el momento.","reference":"Ester 4:10–17; 5:1–8; 7:1–6"},{"stage":"05 · EL PUNTO DECISIVO","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"Los banquetes","text":"El rey recibió favorablemente a Ester. Ella organizó banquetes y preparó la ocasión para revelar su petición.","why":"La valentía de Ester estuvo acompañada de prudencia.","reference":"Ester 4:10–17; 5:1–8; 7:1–6"},{"stage":"06 · LAS CONSECUENCIAS","name":"Ester","role":"Reina judía en Persia que intervino para proteger a su pueblo.","mode":"historico","title":"La amenaza sale a la luz","text":"En el momento oportuno, Ester identificó a Hamán como el responsable de la amenaza contra su pueblo.","why":"La acción valiente de Ester ayudó a cambiar el desenlace.","reference":"Ester 4:10–17; 5:1–8; 7:1–6"}],"nehemias":[{"stage":"01 · EL CONTEXTO","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"Malas noticias de Jerusalén","text":"Nehemías, que servía en la corte persa, se enteró de que las murallas de Jerusalén seguían en ruinas.","why":"La noticia lo afectó porque la ciudad y su pueblo le importaban.","reference":"Nehemías 2:11–18; 3:1–32; 6:15"},{"stage":"02 · EL PRIMER CAMBIO","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"Oración y preparación","text":"Nehemías oró y preparó una petición al rey para poder viajar y ayudar.","why":"Combinó dependencia de Jehová con planificación concreta.","reference":"Nehemías 2:11–18; 3:1–32; 6:15"},{"stage":"03 · EL DESAFÍO","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"Una inspección nocturna","text":"Al llegar a Jerusalén, Nehemías examinó de noche los daños de la muralla antes de explicar sus planes.","why":"Quiso conocer personalmente la situación antes de organizar el trabajo.","reference":"Nehemías 2:11–18; 3:1–32; 6:15"},{"stage":"04 · LA RESPUESTA","name":"Constructores de Jerusalén","role":"Grupo que trabajó en la reconstrucción.","mode":"historico","title":"Manos a la obra","text":"Diferentes familias y grupos comenzaron a reconstruir secciones de la muralla.","why":"La cooperación permitió avanzar en una obra demasiado grande para una sola persona.","reference":"Nehemías 2:11–18; 3:1–32; 6:15"},{"stage":"05 · EL PUNTO DECISIVO","name":"Sanbalat y Tobías","role":"Opositores a la reconstrucción.","mode":"historico","title":"Resistencia y vigilancia","text":"Los enemigos trataron de intimidar y detener la reconstrucción; el pueblo tuvo que mantenerse alerta mientras trabajaba.","why":"La oposición requirió tanto valor como organización.","reference":"Nehemías 2:11–18; 3:1–32; 6:15"},{"stage":"06 · LAS CONSECUENCIAS","name":"Nehemías","role":"Copero del rey persa que dirigió la reconstrucción de la muralla de Jerusalén.","mode":"historico","title":"La muralla se completa","text":"La reconstrucción terminó en 52 días, causando sorpresa entre quienes se oponían.","why":"El resultado fue fruto de fe, trabajo coordinado y perseverancia.","reference":"Nehemías 2:11–18; 3:1–32; 6:15"}],"maria":[{"stage":"01 · EL CONTEXTO","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Una joven en Nazaret","text":"María vivía en Nazaret y estaba comprometida para casarse con José.","why":"Su vida cotidiana cambió de forma inesperada.","reference":"Lucas 1:26–38"},{"stage":"02 · EL PRIMER CAMBIO","name":"Gabriel","role":"Ángel que comunicó a María una noticia extraordinaria.","mode":"historico","title":"La visita de Gabriel","text":"El ángel Gabriel la saludó y le anunció que tendría un hijo llamado Jesús.","why":"Se le comunicó una responsabilidad extraordinaria.","reference":"Lucas 1:26–38"},{"stage":"03 · EL DESAFÍO","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Una pregunta sincera","text":"María preguntó cómo ocurriría aquello, pues todavía no había tenido relaciones con un hombre.","why":"La pregunta buscaba comprender, no rechazar el mensaje.","reference":"Lucas 1:26–38"},{"stage":"04 · LA RESPUESTA","name":"Gabriel","role":"Ángel que comunicó a María una noticia extraordinaria.","mode":"historico","title":"Una explicación y una señal","text":"Gabriel le explicó la intervención del espíritu santo y le habló de su parienta Elisabet.","why":"Recibió información que la ayudó a entender mejor la situación.","reference":"Lucas 1:26–38"},{"stage":"05 · EL PUNTO DECISIVO","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Una respuesta de disposición","text":"María aceptó humildemente la misión que se le había comunicado.","why":"Sus palabras mostraron confianza pese a no conocer todos los detalles.","reference":"Lucas 1:26–38"},{"stage":"06 · LAS CONSECUENCIAS","name":"María","role":"Joven de Nazaret elegida para ser la madre de Jesús.","mode":"historico","title":"Un comienzo decisivo","text":"El relato prepara el escenario para el nacimiento de Jesús y su papel en el propósito divino.","why":"Su ejemplo une humildad, reflexión y disposición a actuar.","reference":"Lucas 1:26–38"}],"samaritano":[{"stage":"01 · EL CONTEXTO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Una pregunta a Jesús","text":"Un experto en la Ley preguntó a Jesús quién debía ser considerado su prójimo. Jesús respondió con una parábola.","why":"Los personajes de la parábola ilustran una enseñanza, no están presentados como un registro de testigos históricos.","reference":"Lucas 10:25–37"},{"stage":"02 · EL PRIMER CAMBIO","name":"Viajero de la parábola","role":"Figura de una parábola de Jesús; no es una persona histórica identificada.","mode":"parabola","title":"El viajero herido","text":"En la historia, un hombre viajaba de Jerusalén a Jericó cuando unos ladrones lo atacaron y lo dejaron gravemente herido.","why":"El problema de fondo es la necesidad de alguien vulnerable.","reference":"Lucas 10:25–37"},{"stage":"03 · EL DESAFÍO","name":"Sacerdote de la parábola","role":"Figura de una parábola de Jesús; no es una persona histórica identificada.","mode":"parabola","title":"Pasan sin ayudar","text":"Un sacerdote y después un levita vieron al herido, pero continuaron por el camino sin prestarle ayuda.","why":"El cargo religioso no garantizó una respuesta compasiva.","reference":"Lucas 10:25–37"},{"stage":"04 · LA RESPUESTA","name":"Samaritano de la parábola","role":"Figura de una parábola de Jesús que se destaca por su compasión.","mode":"parabola","title":"Un samaritano se detiene","text":"Un samaritano, de un pueblo con tensiones históricas con los judíos, sintió compasión y atendió las heridas del hombre.","why":"La ayuda vino de quien menos se esperaba.","reference":"Lucas 10:25–37"},{"stage":"05 · EL PUNTO DECISIVO","name":"Samaritano de la parábola","role":"Figura de una parábola de Jesús que se destaca por su compasión.","mode":"parabola","title":"Se ocupa de su recuperación","text":"El samaritano llevó al herido a una posada, lo cuidó y dejó dinero para que continuaran atendiéndolo.","why":"La compasión se convirtió en tiempo, esfuerzo y recursos concretos.","reference":"Lucas 10:25–37"},{"stage":"06 · LAS CONSECUENCIAS","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"¿Quién fue el prójimo?","text":"Jesús invitó a reconocer que el prójimo fue quien actuó con misericordia.","why":"La pregunta final no es a quién limitar nuestro amor, sino cómo mostrarlo.","reference":"Lucas 10:25–37"}],"hijo":[{"stage":"01 · EL CONTEXTO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Dos hijos y una herencia","text":"En una parábola de Jesús, un padre tenía dos hijos. El menor pidió anticipadamente la parte de la herencia que le correspondía.","why":"La petición inicia una historia sobre decisiones y relaciones familiares.","reference":"Lucas 15:11–32"},{"stage":"02 · EL PRIMER CAMBIO","name":"Hijo menor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"Una salida precipitada","text":"El hijo menor viajó lejos y malgastó sus bienes viviendo irresponsablemente.","why":"La libertad que buscaba terminó acompañada de grandes pérdidas.","reference":"Lucas 15:11–32"},{"stage":"03 · EL DESAFÍO","name":"Hijo menor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"Necesidad y reflexión","text":"Cuando llegó el hambre, tuvo que cuidar cerdos y se vio en una situación miserable. Entonces reflexionó sobre su vida.","why":"Reconocer el error fue el comienzo del cambio.","reference":"Lucas 15:11–32"},{"stage":"04 · LA RESPUESTA","name":"Hijo menor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"Decide regresar","text":"El joven decidió volver a su padre y admitir que había pecado, sin exigir recuperar su posición anterior.","why":"El arrepentimiento se expresó en un cambio de dirección.","reference":"Lucas 15:11–32"},{"stage":"05 · EL PUNTO DECISIVO","name":"Padre de la parábola","role":"Figura de la parábola de Jesús que muestra misericordia.","mode":"parabola","title":"Un recibimiento inesperado","text":"El padre lo vio llegar, corrió a recibirlo y celebró su retorno.","why":"La reacción del padre ilustra una misericordia llena de afecto.","reference":"Lucas 15:11–32"},{"stage":"06 · LAS CONSECUENCIAS","name":"Hijo mayor de la parábola","role":"Figura de la parábola del hijo que regresa; no es una persona identificada.","mode":"parabola","title":"El hermano mayor","text":"El hermano mayor se molestó por la celebración y el padre le explicó por qué era motivo de alegría recuperar a su hijo.","why":"La parábola también invita a examinar nuestra reacción cuando otros reciben perdón.","reference":"Lucas 15:11–32"}],"panes":[{"stage":"01 · EL CONTEXTO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Una multitud sigue a Jesús","text":"Mucha gente acudió a escuchar a Jesús y estaba lejos de los lugares donde podía conseguir alimentos.","why":"La necesidad de la gente no pasó inadvertida para Jesús.","reference":"Juan 6:1–13"},{"stage":"02 · EL PRIMER CAMBIO","name":"Andrés","role":"Discípulo de Jesús que señaló que había un muchacho con cinco panes y dos pescados.","mode":"historico","title":"Una cantidad diminuta","text":"Entre los presentes había cinco panes de cebada y dos pescados, insuficientes para una multitud tan grande.","why":"La cantidad disponible hacía evidente el problema.","reference":"Juan 6:1–13"},{"stage":"03 · EL DESAFÍO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Jesús da gracias","text":"Jesús organizó a la multitud, tomó el alimento y dio gracias antes de distribuirlo.","why":"El relato presenta una respuesta calmada y agradecida ante la necesidad.","reference":"Juan 6:1–13"},{"stage":"04 · LA RESPUESTA","name":"Muchacho con panes","role":"Joven anónimo que llevaba cinco panes y dos pescados.","mode":"historico","title":"Todos reciben comida","text":"El alimento se repartió y los presentes pudieron comer hasta quedar satisfechos.","why":"La intervención de Jesús atendió una necesidad concreta de las personas.","reference":"Juan 6:1–13"},{"stage":"05 · EL PUNTO DECISIVO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Recogen las sobras","text":"Después, Jesús indicó que recogieran los pedazos que quedaban para que nada se desperdiciara.","why":"La abundancia no eliminó la importancia de evitar el desperdicio.","reference":"Juan 6:1–13"},{"stage":"06 · LAS CONSECUENCIAS","name":"Discípulos","role":"Seguidores de Jesús que recogieron las sobras.","mode":"historico","title":"Doce canastas","text":"Se reunieron doce canastas con los restos de los panes, una señal de la magnitud del milagro.","why":"El relato destaca tanto la generosidad como el buen uso de los recursos.","reference":"Juan 6:1–13"}],"pedro":[{"stage":"01 · EL CONTEXTO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Una noche de miedo","text":"La noche en que arrestaron a Jesús, Pedro lo siguió hasta el patio de la casa del sumo sacerdote.","why":"Su deseo de estar cerca de Jesús convivía con el temor al peligro.","reference":"Lucas 22:54–62; Juan 21:15–17"},{"stage":"02 · EL PRIMER CAMBIO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Primera negación","text":"Una sirvienta identificó a Pedro como seguidor de Jesús, pero él negó conocerlo.","why":"El miedo empezó a influir en sus palabras.","reference":"Lucas 22:54–62; Juan 21:15–17"},{"stage":"03 · EL DESAFÍO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"La negación se repite","text":"Pedro negó conocer a Jesús otras dos veces y terminó oyendo cantar al gallo.","why":"La presión lo llevó a actuar de un modo contrario a sus intenciones.","reference":"Lucas 22:54–62; Juan 21:15–17"},{"stage":"04 · LA RESPUESTA","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Reconoce su error","text":"Pedro recordó lo que Jesús le había advertido y lloró amargamente.","why":"La tristeza sincera mostró que no le era indiferente lo ocurrido.","reference":"Lucas 22:54–62; Juan 21:15–17"},{"stage":"05 · EL PUNTO DECISIVO","name":"Jesús","role":"Maestro que usaba relatos y parábolas para enseñar verdades espirituales.","mode":"historico","title":"Un encuentro después","text":"Después de su resurrección, Jesús habló con Pedro y le preguntó repetidamente si lo amaba.","why":"La conversación le permitió reafirmar su amor.","reference":"Lucas 22:54–62; Juan 21:15–17"},{"stage":"06 · LAS CONSECUENCIAS","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Una responsabilidad renovada","text":"Jesús encomendó a Pedro alimentar y cuidar a sus ovejas.","why":"Su error no tuvo por qué definir el resto de su vida.","reference":"Lucas 22:54–62; Juan 21:15–17"}],"dorcas":[{"stage":"01 · EL CONTEXTO","name":"Dorcas / Tabita","role":"Discípula de Jope conocida por ayudar a las viudas y hacer buenas obras.","mode":"historico","title":"Una discípula generosa","text":"Dorcas, llamada también Tabita, vivía en Jope y era conocida por las buenas obras y la ayuda que prestaba.","why":"Su fe se notaba en cómo trataba a personas necesitadas.","reference":"Hechos 9:36–42"},{"stage":"02 · EL PRIMER CAMBIO","name":"Discípulos de Jope","role":"Grupo que llamó a Pedro cuando murió Dorcas.","mode":"historico","title":"Dorcas enferma","text":"Dorcas enfermó y murió. La comunidad quedó profundamente triste.","why":"Su ausencia mostró cuánto había significado para otros.","reference":"Hechos 9:36–42"},{"stage":"03 · EL DESAFÍO","name":"Viuda de Jope","role":"Una de las viudas del relato; las Escrituras no conservan su nombre.","mode":"historico","title":"Las viudas recuerdan","text":"Cuando llegó Pedro, varias viudas le mostraron prendas que Dorcas había confeccionado mientras estaba con ellas.","why":"Las prendas eran pruebas tangibles de su bondad.","reference":"Hechos 9:36–42"},{"stage":"04 · LA RESPUESTA","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Pedro entra y ora","text":"Pedro pidió que los demás salieran de la habitación y se arrodilló a orar.","why":"La escena presenta un momento solemne de dependencia de Dios.","reference":"Hechos 9:36–42"},{"stage":"05 · EL PUNTO DECISIVO","name":"Pedro","role":"Apóstol de Jesús que aprendió del perdón después de negarlo.","mode":"historico","title":"Tabita vuelve a vivir","text":"Pedro se dirigió a Dorcas y ella abrió los ojos. Después la ayudó a levantarse.","why":"La noticia transformó el duelo en alegría.","reference":"Hechos 9:36–42"},{"stage":"06 · LAS CONSECUENCIAS","name":"Creyentes de Jope","role":"Grupo que conoció el milagro y se fortaleció.","mode":"historico","title":"Muchos se enteran","text":"La resurrección se conoció por toda Jope y muchas personas llegaron a creer.","why":"El final resalta tanto el milagro como la vida generosa que Dorcas había llevado.","reference":"Hechos 9:36–42"}],"lidia":[{"stage":"01 · EL CONTEXTO","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Una comerciante en Filipos","text":"Lidia era vendedora de púrpura, originaria de Tiatira, y se encontraba en Filipos.","why":"Su oficio y su presencia en la ciudad forman parte del contexto del relato.","reference":"Hechos 16:11–15, 40"},{"stage":"02 · EL PRIMER CAMBIO","name":"Pablo","role":"Apóstol que anunció el mensaje cristiano en Filipos.","mode":"historico","title":"Una reunión junto al río","text":"Pablo y sus compañeros fueron a un lugar fuera de la puerta de la ciudad donde se reunían mujeres para orar.","why":"Allí comenzaron a conversar sobre el mensaje cristiano.","reference":"Hechos 16:11–15, 40"},{"stage":"03 · EL DESAFÍO","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Lidia escucha con atención","text":"Lidia prestó atención a lo que Pablo explicó, y el relato dice que Jehová abrió su corazón para responder.","why":"La escucha atenta fue el primer paso de su respuesta.","reference":"Hechos 16:11–15, 40"},{"stage":"04 · LA RESPUESTA","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Una decisión pública","text":"Lidia y los de su casa se bautizaron.","why":"La decisión mostró que lo que había escuchado tenía consecuencias para su vida.","reference":"Hechos 16:11–15, 40"},{"stage":"05 · EL PUNTO DECISIVO","name":"Lidia","role":"Comerciante de púrpura que escuchó a Pablo en Filipos.","mode":"historico","title":"Ofrece alojamiento","text":"Lidia invitó insistentemente a Pablo y a sus compañeros a quedarse en su casa.","why":"Su hospitalidad ayudó a quienes estaban enseñando en Filipos.","reference":"Hechos 16:11–15, 40"},{"stage":"06 · LAS CONSECUENCIAS","name":"Pablo","role":"Apóstol que anunció el mensaje cristiano en Filipos.","mode":"historico","title":"Una casa abierta","text":"Después de salir de prisión, Pablo y Silas se reunieron con los hermanos en casa de Lidia antes de continuar su viaje.","why":"Su hogar se convirtió en un lugar de apoyo para otros.","reference":"Hechos 16:11–15, 40"}]};
